CREATE TABLE IF NOT EXISTS "user" (id text PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, "emailVerified" boolean NOT NULL DEFAULT false, image text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS session (id text PRIMARY KEY, "expiresAt" timestamptz NOT NULL, token text NOT NULL UNIQUE, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now(), "ipAddress" text, "userAgent" text, "userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE);
CREATE INDEX ON session("userId");
CREATE TABLE IF NOT EXISTS account (id text PRIMARY KEY, "accountId" text NOT NULL, "providerId" text NOT NULL, "userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" timestamptz, "refreshTokenExpiresAt" timestamptz, scope text, password text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE INDEX ON account("userId");
CREATE TABLE IF NOT EXISTS verification (id text PRIMARY KEY, identifier text NOT NULL, value text NOT NULL, "expiresAt" timestamptz NOT NULL, "createdAt" timestamptz DEFAULT now(), "updatedAt" timestamptz DEFAULT now());
CREATE INDEX ON verification(identifier);
CREATE TABLE roles (id text PRIMARY KEY, name text NOT NULL UNIQUE);
CREATE TABLE permissions (id text PRIMARY KEY);
CREATE TABLE role_permissions (role_id text REFERENCES roles(id), permission_id text REFERENCES permissions(id), PRIMARY KEY(role_id,permission_id));
CREATE TABLE staff (user_id text PRIMARY KEY REFERENCES "user"(id), role_id text NOT NULL REFERENCES roles(id), active boolean NOT NULL DEFAULT true);
CREATE TABLE clients (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, email text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE case_statuses (id text PRIMARY KEY);
CREATE TABLE cases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), number bigint GENERATED ALWAYS AS IDENTITY UNIQUE, client_id uuid NOT NULL REFERENCES clients(id), country text NOT NULL, visa_type text NOT NULL, status text NOT NULL DEFAULT 'New' REFERENCES case_statuses(id), responsible_id text NOT NULL REFERENCES staff(user_id), escalation_id text REFERENCES staff(user_id), deadline timestamptz, revision int NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ON cases(responsible_id);
CREATE INDEX ON cases(client_id);
CREATE INDEX ON cases(status,deadline);
CREATE TABLE tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid NOT NULL REFERENCES cases(id), title text NOT NULL, description text NOT NULL DEFAULT '', responsible_id text NOT NULL REFERENCES staff(user_id), escalation_id text REFERENCES staff(user_id), deadline timestamptz NOT NULL, status text NOT NULL DEFAULT 'To do' CHECK(status IN ('To do','In progress','Completed')), creator_id text NOT NULL REFERENCES staff(user_id), completed_at timestamptz, revision int NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK ((status='Completed')=(completed_at IS NOT NULL)));
CREATE INDEX ON tasks(case_id,responsible_id,status);
CREATE INDEX ON tasks(deadline) WHERE status <> 'Completed';
CREATE TABLE documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid NOT NULL REFERENCES cases(id), type text NOT NULL CHECK(type IN ('Passport','Bank Statement','Insurance','Other')), name text NOT NULL, archived boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ON documents(case_id);
CREATE TABLE document_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), document_id uuid NOT NULL REFERENCES documents(id), version int NOT NULL, filename text NOT NULL, storage_key text NOT NULL UNIQUE, mime text NOT NULL, size bigint NOT NULL, checksum text NOT NULL, uploaded_by text NOT NULL REFERENCES staff(user_id), source text NOT NULL CHECK(source IN ('website','telegram')), review_status text NOT NULL DEFAULT 'Uploaded' CHECK(review_status IN ('Uploaded','Under review','Approved')), reviewed_by text REFERENCES staff(user_id), reviewed_at timestamptz, expires_at date, scan_status text NOT NULL DEFAULT 'pending' CHECK(scan_status IN ('pending','clean','infected','failed')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(document_id,version));
CREATE TABLE telegram_links (user_id text PRIMARY KEY REFERENCES staff(user_id), telegram_id text UNIQUE, token_hash text UNIQUE, expires_at timestamptz);
CREATE TABLE telegram_updates (id bigint PRIMARY KEY, received_at timestamptz NOT NULL DEFAULT now(), body jsonb NOT NULL, state text NOT NULL DEFAULT 'pending', attempts int NOT NULL DEFAULT 0, next_at timestamptz NOT NULL DEFAULT now(), locked_at timestamptz);
CREATE TABLE telegram_uploads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id text NOT NULL REFERENCES staff(user_id), update_id bigint NOT NULL UNIQUE REFERENCES telegram_updates(id), file_id text NOT NULL, filename text NOT NULL, case_id uuid REFERENCES cases(id), document_id uuid REFERENCES documents(id), type text, state text NOT NULL DEFAULT 'case', expires_at timestamptz NOT NULL DEFAULT now()+interval '30 minutes', version_id uuid REFERENCES document_versions(id));
CREATE TABLE notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id text NOT NULL REFERENCES staff(user_id), case_id uuid REFERENCES cases(id), title text NOT NULL, message text NOT NULL, read_at timestamptz, dedupe_key text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ON notifications(user_id,created_at DESC);
CREATE TABLE jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL, payload jsonb NOT NULL, dedupe_key text NOT NULL UNIQUE, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','processing','sent','failed','cancelled')), attempts int NOT NULL DEFAULT 0, run_at timestamptz NOT NULL DEFAULT now(), locked_at timestamptz, last_error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ON jobs(status,run_at);
CREATE TABLE backup_deliveries (version_id uuid PRIMARY KEY REFERENCES document_versions(id), state text NOT NULL DEFAULT 'pending', message_id text, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, user_id text REFERENCES "user"(id), action text NOT NULL, entity text NOT NULL, entity_id text NOT NULL, case_id uuid REFERENCES cases(id), source text NOT NULL DEFAULT 'website', detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ON audit_logs(case_id,created_at DESC);
CREATE FUNCTION audit_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Audit log is append-only'; END $$;
CREATE TRIGGER audit_no_change BEFORE UPDATE OR DELETE ON audit_logs FOR EACH ROW EXECUTE FUNCTION audit_immutable();
CREATE TABLE system_settings (id text PRIMARY KEY, value jsonb NOT NULL);
INSERT INTO system_settings VALUES ('general','{"timezone":"Asia/Tashkent","maxFileMb":20,"reminderDays":[3,1],"backupEnabled":false,"teamEnabled":false}') ON CONFLICT DO NOTHING;
CREATE TABLE rate_limits (key text PRIMARY KEY, hits int NOT NULL, reset_at timestamptz NOT NULL);
